sysauto_script.script:
// ACL Sentinel — Daily Delta Scan
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function () {
    var engine = new AclSentinelEngine();
    var scanId = engine.runScan('delta', 'local');
    if (scanId) {
        gs.info('ACL Sentinel daily scan completed: ' + scanId);
    } else {
        gs.error('ACL Sentinel daily scan failed to start');
    }
})();
